import{_ as o,o as t,c as a,ah as i}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Research: The COFAG Millions (Benko & the Signa System)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/cofag-skandal.md","filePath":"en/recherche/cofag-skandal.md"}'),n={name:"en/recherche/cofag-skandal.md"};function s(r,e,l,h,c,d){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="research-the-cofag-millions-benko-the-signa-system" tabindex="-1">Research: The COFAG Millions (Benko &amp; the Signa System) <a class="header-anchor" href="#research-the-cofag-millions-benko-the-signa-system" aria-label="Permalink to &quot;Research: The COFAG Millions (Benko &amp; the Signa System)&quot;">​</a></h1><p><strong>Corona aid as fuel for a sinking ship?</strong></p><p>The COVID-19 Federal Financing Agency (COFAG) was founded during the pandemic to help companies quickly and unbureaucratically. In our mockumentary, we shed light on how this system was used by large investors like René Benko, while small businesses often waited months for help.</p><hr><h2 id="facts-on-the-benko-case" tabindex="-1">Facts on the Benko Case <a class="header-anchor" href="#facts-on-the-benko-case" aria-label="Permalink to &quot;Facts on the Benko Case&quot;">​</a></h2><h3 id="_1-the-18-7-million-package" tabindex="-1">1. The 18.7 Million Package <a class="header-anchor" href="#_1-the-18-7-million-package" aria-label="Permalink to &quot;1. The 18.7 Million Package&quot;">​</a></h3><p>Companies from the Signa network received a total of at least <strong>18.7 million euros</strong> in subsidies from COFAG.</p><ul><li><strong>EU Limit Exceeded?</strong> The opposition criticizes that this clearly exceeded the EU-wide limit of 14 million euros per corporate group.</li><li><strong>Chalet N:</strong> Especially controversial is the subsidy for the luxury Chalet N in Lech, which received around 1.1 million euros, although critics say it actually functioned as a private residence.</li></ul><h3 id="_2-the-forcibly-produced-witness" tabindex="-1">2. The &quot;Forcibly Produced&quot; Witness <a class="header-anchor" href="#_2-the-forcibly-produced-witness" aria-label="Permalink to &quot;2. The &quot;Forcibly Produced&quot; Witness&quot;">​</a></h3><p>In May 2024, René Benko was forcibly produced by the police to testify before the committee of inquiry after failing to appear several times without excuse.</p><ul><li><strong>The Silence:</strong> Benko refused to answer almost all questions, citing ongoing investigation proceedings.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>The COFAG story is the modern peak of pointillism.</p><ul><li><strong>Two-Tier Subsidy System:</strong> While Heidi Horten shone through donations, Benko secured his empire through privileged access to state funds.</li></ul><hr><p><em>Sources: Protocols of the COFAG Inquiry Committee (2024), Court of Audit reports, analysis by Standard.</em></p>',17)])])}const f=o(n,[["render",s]]);export{m as __pageData,f as default};
